 <p style=\"margin:0;font-size:13px;color:#888888;\">This is an automated notification. Please do not reply directly to this email.</p>\r\n                                        <p style=\"margin-top:15px;font-size:13px;color:#999999;\">Need help? <a href=\"mailto:support@deccanfinltd.world\" style=\"color:#031f73;text-decoration:none;font-weight:bold;\">support@deccanfinltd.world</a></p>\r\n                                        <p style=\"margin-top:20px;font-size:12px;color:#bbbbbb;\">©️ 2026 Deccan Finance. All Rights Reserved.</p>\r\n                                    </td>\r\n                                </tr>\r\n                            </tbody></table>\r\n                        </td>\r\n                    </tr>\r\n                </tbody></table>\r\n            </td>\r\n        </tr>\r\n    </tbody></table>', 'support@deccanfinltd.world', 'SUCCESS', NULL, '2026-07-23 14:23:02'),
(55, 'test@gmail.com,', '', '', 'Deccan Finance - Application Under Review ⏳', '<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"UTF-8\">\n<title>Application Under Review ⏳</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f7fb;font-family:Arial,Helvetica,sans-serif;\">\n<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f7fb;padding:40px 0;\">\n<tr>\n<td align=\"center\">\n<table width=\"600\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 8px 25px rgba(0,0,0,.08);\">\n<tr>\n<td align=\"center\" style=\"padding:35px 20px;background:linear-gradient(135deg,#031f73,#02144a);\">\n<img src=\"https://deccanfinltd.world/assets/img/logo.png\" width=\"80\" style=\"display:block;margin-bottom:10px;\">\n<h1 style=\"margin:10px 0 5px;color:#fff;font-size:30px;\">Deccan Finance</h1>\n<p style=\"margin:0;color:#e7e7ff;font-size:15px;\">Secure. Simple. Trusted.</p>\n</td>\n</tr>\n<tr>\n<td style=\"padding:40px;\">\n<h2 style=\"margin-top:0;color:#222;font-size:28px;\">Application Under Review ⏳</h2>\n<p style=\"color:#555;font-size:16px;line-height:28px;\">Hello <strong>TEst shsbhs</strong>,</p>\n<p style=\"color:#555;font-size:16px;line-height:28px;\">Thank you for submitting your application to Deccan Finance.</p>\n<p style=\"color:#555;font-size:16px;line-height:28px;\">Your application has been received and is currently <strong>under review</strong>. Our compliance team will verify your details within the next <strong>24-48 hours</strong>.</p>\n<table width=\"100%\" cellpadding=\"12\" cellspacing=\"0\" style=\"margin:30px 0;background:#f8f9ff;border-radius:12px;\">\n<tr>\n<td style=\"color:#666;\">Application ID</td>\n<td align=\"right\" style=\"font-size:18px;color:#222;\"><strong>FR-316501</strong></td>\n</tr>\n<tr>\n<td style=\"color:#666;\">Submission Date</td>\n<td align=\"right\" style=\"color:#222;\">17 Aug 2026 03:57 PM</td>\n</tr>\n</table>\n<div style=\"backgr