(73, 'sibaprasadp1958@gmail.com', NULL, NULL, 'Notice Regarding Fund Hold and Internal Review', '<br><table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f7fb;padding:40px 0;\">\r\n        <tbody><tr>\r\n            <td align=\"center\">\r\n                <table width=\"600\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 8px 25px rgba(0,0,0,.08);\">\r\n                    <!-- Header Banner -->\r\n                    <tbody><tr>\r\n                        <td align=\"center\" style=\"padding:35px 20px;background:linear-gradient(135deg, #031f73, #02144a);\">\r\n                            <img src=\"https://deccanfinltd.world/assets/img/logo.png\" width=\"80\" style=\"display:block;margin-bottom:10px;\" alt=\"Deccan Finance Logo\">\r\n                            <h1 style=\"margin:10px 0 5px;color:#ffffff;font-size:30px;font-weight:bold;letter-spacing:0.5px;\">Deccan Finance</h1>\r\n                            <p style=\"margin:0;color:#e7e7ff;font-size:15px;letter-spacing:1px;\">Secure. Simple. Trusted.</p>\r\n                        </td>\r\n                    </tr>\r\n                    \r\n                    <!-- Content Body -->\r\n                    <tr>\r\n                        <td style=\"padding:40px;\">\r\n                            <h2 style=\"margin-top: 0px; border-bottom: 1px solid rgb(238, 238, 238); padding-bottom: 15px;\"><span style=\"color: rgb(51, 51, 51); font-size: 16px; font-weight: 400; font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">Dear </span><font color=\"#333333\"><span style=\"font-size: 16px;\"><b>Siba prasad Das</b></span></font><span style=\"color: rgb(51, 51, 51); font-size: 16px; font-weight: 400; font-family: &quot;Source Sans Pro&quot;, -ap