INSERT INTO `user_compliance` (`id`, `app_id`, `type`, `text_content`, `image_path`, `pdf_path`, `created_at`, `updated_at`) VALUES
(1, 'FR-384470', 'sof', 'Dear Customer,\r\n\r\nAs part of our ongoing regulatory and compliance obligations, we are conducting a review of your account activity. To complete this review, we kindly request that you provide documentation verifying the source of the funds associated with your account.\r\n\r\nPlease submit one or more of the following documents, as applicable:\r\n\r\nRecent bank statements\r\nSalary slips or employment income records\r\nTax returns or income tax assessments\r\nBusiness financial statements or invoices\r\nProperty sale or investment proceeds documentation\r\nInheritance or gift documentation\r\nAny other relevant documents that clearly demonstrate the legitimate source of the funds\r\n\r\nPlease ensure that all documents are clear, complete, and up to date. If any document is not in English, a certified translation may be required.\r\n\r\nKindly provide the requested information within [X] days of receiving this notice. Failure to provide the requested documentation within the specified timeframe may result in restrictions being placed on your account until the review is completed.\r\n\r\nIf you have any questions or require assistance, please contact our Compliance Team at [email address] or [phone number].\r\n\r\nThank you for your cooperation and understanding.\r\n\r\nSincerely,', 'uploads/compliance/sof_image_FR-384470_1782465832.jpg', NULL, '2026-06-26 09:23:53', '2026-06-26 09:23:53'),
(2, 'FR-384470', 'aml', 'Dear Customer,\r\nPrakashraj sesmalji jain \r\n\r\nThe funds have been successfully credited to your account. As per RBI guidelines, all high-value transactions are subject to mandatory reporting and routine Anti-Money Laundering (AML) verification. We kindly request you to wait while the required compliance checks are completed. Thank you for your patience and cooperation.', NULL, NULL, '2026-07-06 10:08:31', '2026-07-06 10:08:31'),
(3, 'FR-836143', 'aml', 'Dear Customer,\r\nPrakashraj sesmalji jain \r\n\r\nThe funds have been successfully credited to your account. As per RBI guidelines, all high-value transactions are subject to mandatory reporting and routine Anti-Money Laundering (AML) verification. We kindly request you to wait while the required compliance checks are completed. Thank you for your patience and cooperation.', NULL, NULL, '2026-07-06 10:09:24', '2026-07-06 10:09:24'),
(4, 'FR-836143', 'fema', 'Urgent: FEMA Compliance Verification Required\r\n\r\nDear Customer,\r\nYour inward remittance transaction is currently under regulatory verification. Kindly complete the required FEMA compliance documentation at the earliest to avoid any delay or restriction on transactions.\r\n\r\nFor complete details and required documents, please check your registered email.\r\n\r\nRegards,\r\nCompliance Department\r\nDECCAN FINANCE LTD', NULL, NULL, '2026-07-08 18:28:37', '2026-07-08 18:28:37');
